#include "Modules/Module.h"

#define LOOM_MAX_HOURLY_TIPS 32

struct TippingBucketData {
    uint32_t totalTips;
    uint32_t hourlyTips;
};

/**
 * Class used to handle keeping track of tips generated by interrupts
 *
 * NOTE: It is recommended to use the tipping bucket with a connection to ground
 * and an input pull-up resistor instead of a connection to VCC and an input
 * pull-down resistor.
 * In the second case only, a "ghost tip" has been observed in the following
 * sleep cycle if two or more tips are counted in the current cycle.
 * This problem is not fully understood, but has not been observed in the first
 * case.
 *
 * @author Quinn Yockey, Will Richards
 */
class Loom_TippingBucket : public Module{
  protected:
    void initialize() override;
    void measure() override;
    void displayData() override;
    void powerDown() override {};
    void powerUp() override {};
    void writeCsvHeader1(File *csv) override;
    void writeCsvHeader2(File *csv) override;
    void writeCsvBody(File *csv) override;

  public:
    Loom_TippingBucket(
        struct TippingBucketData *data,
        uint32_t debounceMillis,
        uint8_t pin,
        uint32_t detectionMode = INPUT_PULLUP,
        uint32_t triggerMode = FALLING
    );
    static void tipHandle(void);

  private:
    static void tipDetect(void);
    static uint32_t debounceMillis;
    uint8_t pin;
    uint32_t detectionMode;
    uint32_t triggerMode;

    static volatile struct TippingBucketData *data;

    /* Circular buffer */
    static volatile uint32_t timestamps[LOOM_MAX_HOURLY_TIPS];
    static volatile uint8_t indexLatest;
    static volatile uint8_t indexEarliest;
    static volatile bool overflow;

    uint32_t getHourlyTips();
};
